const test = require('node:test')
const assert = require('node:assert/strict')
const { decodeSettleFeesWithTEECalldata } = require('../src/abiCodec')

// This exact calldata was produced by `cast calldata` against the real
// `settleFeesWithTEE((address,address,uint256,bytes32,uint256,bytes)[])`
// signature — it is ground truth for what a correct ABI encoder produces,
// not something this test invented.
const TWO_ITEM_CALLDATA =
  ''

test('decodeSettleFeesWithTEECalldata decodes a two-item batch matching cast-generated ground truth', () => {
  const { selector, settlements } = decodeSettleFeesWithTEECalldata(TWO_ITEM_CALLDATA)

  assert.equal(selector, '0x8be74119')
  assert.equal(settlements.length, 2)

  assert.equal(settlements[0].user, '0x7f11f64a7d470d2b0a49cac36837ffa49f8c63e9')
  assert.equal(settlements[0].provider, '0x87a13337f0d4b2b08cce9189dbe9555690828ed4')
  assert.equal(settlements[0].totalFee, 10000000000000000n)
  assert.equal(settlements[0].requestsHash, '0x' + '11'.repeat(32))
  assert.equal(settlements[0].nonce, 0n)
  assert.equal(settlements[0].signature, '0x1234')

  assert.equal(settlements[1].user, '0x7f11f64a7d470d2b0a49cac36837ffa49f8c63e9')
  assert.equal(settlements[1].provider, '0xa02b95aa6886b1116c4f334ede00381511e31a09')
  assert.equal(settlements[1].totalFee, 20000000000000000n)
  assert.equal(settlements[1].requestsHash, '0x' + '22'.repeat(32))
  assert.equal(settlements[1].signature, '0x5678')
})

test('decodeSettleFeesWithTEECalldata handles a single-item batch', () => {
  const single =
    ''
  const { settlements } = decodeSettleFeesWithTEECalldata(single)
  assert.equal(settlements.length, 1)
  assert.equal(settlements[0].provider, '0xa02b95aa6886b1116c4f334ede00381511e31a09')
})
